/* SR2E — hotbar slot 10. Adds to lifetime Karma; one-tenth (rounded up) is the Karma Pool, the rest Good Karma (p.190–191).
   See docs/MACROS.md for the VIA macro-pad layout. */
const tokens = canvas.tokens?.controlled ?? [];
if (!tokens.length) return ui.notifications.warn("Select one or more tokens first.");
const actors = tokens.map(t => t.actor).filter(Boolean);
const data = await foundry.applications.api.DialogV2.prompt({
  window: { title: `Award Karma — ${actors.length} character(s)` },
  content: `<div class="form-group"><label>Karma each</label>
    <input type="number" name="amount" value="1" min="0" autofocus></div>`,
  ok: { label: "Award", callback: (ev, btn) => new FormDataExtended(btn.form).object }
}).catch(() => null);
if (!data) return;
const amt = Number(data.amount) || 0;
if (!amt) return;
for (const a of actors) {
  if (!a.system.karma) continue;   // only characters carry Karma
  // The book's split (p.190–191): Total grows by the award; the Karma Pool is one-tenth of Total, rounded up, and the
  // rest of the award becomes Good Karma. game.sr2e.awardKarma applies the shared transition (karma-advance.mjs).
  await game.sr2e.awardKarma(a, amt);
}
ui.notifications.info(`Awarded ${amt} Karma to ${actors.length} character(s).`);
